import {membershipPurchaseTiles} from './membership-summary.mjs';
import {toolBanner} from './tool-banner.mjs';
import {keys,list,projects,profile} from './state.mjs';
import {literatureKey} from './literature-model.mjs';
import {esc,icon} from './ui.mjs';
const $=selector=>document.querySelector(selector);
export function membershipSnapshot({projectRows=[],drafts=[],papers=[],reports=[],reportError=false}={}){
 // Persisted local records are not requests, credits or billable usage.
 return {projects:projectRows.length,assets:reportError?null:drafts.length+reports.length,papers:papers.length,reports:reportError?null:reports.length};
}
const features=[
 ['pen','写作与修改','整理大纲、手动编辑与保存草稿',[['#category/writing','开始写作'],['#category/reduce','修改段落']]],
 ['book','文献研读','管理文献、核对原文与整理笔记',[['#category/literature','打开文献库']]],
 ['search','论文检测','与自备材料进行文本比对',[['#category/detection','查看材料比对']]],
 ['chart','PPT 与科研绘图','编辑演示文稿，按真实数据绘图',[['#category/ppt','创作 PPT'],['#category/research','科研绘图']]],
 ['file','格式排版','保留原件、检查格式并导出副本',[['#category/format','开始排版']]]
];
export function mountMembership({modal,reportRows=[],reportError=false}){
 const counts=membershipSnapshot({projectRows:projects(),drafts:list(keys.drafts),papers:list(literatureKey),reports:reportRows,reportError}),name=String(profile().name||'研究者');
 const stats=[['folder','本地项目',counts.projects,'#projects?scope=local'],['file','本地成果',counts.assets,'#assets?scope=local&category=all'],['book','本地文献',counts.papers,'#category/literature'],['search','本地比对报告',counts.reports,'#assets?scope=local&category=detection']];
 $('.dashboard').innerHTML=`${toolBanner('membership',{description:'管理可用服务与保存空间，查看真实使用记录。',actions:`<a class="btn primary" href="#membership/plans">查看购买方案 ${icon('arrow',16)}</a><a class="btn secondary" href="#membership?scope=account">账户服务与权益</a>`})}<div class="member-services-summary"><section class="member-account" aria-label="本地保存范围"><div class="member-identity"><span class="member-avatar">${esc(name.slice(0,1)||'研')}</span><div><div class="member-name"><h2>${esc(name)}</h2><span class="member-pill">本地内容</span></div><p>当前浏览器的研究资料 · 与账户内容分别保存</p></div></div><a class="member-account-link" href="#account?view=usage">查看账户真实用量 ${icon('arrow',15)}</a></section>${membershipPurchaseTiles()}<div class="member-layout"><div class="member-main"><section class="card member-card"><header><h2>本地资料概况</h2><span class="member-pill mint">已保存记录</span></header><div class="member-stats">${stats.map(([ico,label,value,url])=>`<a href="${url}" aria-label="${label}${value===null?'数量暂时无法读取':value+' 条'}"><span>${icon(ico,22)}${label}</span><b>${value===null?'—':value.toLocaleString('zh-CN')}</b></a>`).join('')}</div><p class="member-caption">数量来自已保存记录，包含归档项目与历史成果；不代表 AI 调用、会员额度或付费消耗。</p>${reportError?'<p class="member-warning" role="status">比对报告暂时无法读取，成果总数与报告数暂不显示。其他本地记录不受影响。</p>':''}</section><section class="card member-card member-features" id="member-features"><header><h2>当前可用工具</h2><span class="member-pill">以各工具说明为准</span></header><div class="member-feature-grid">${features.map(([ico,title,description,links])=>`<article><span class="member-feature-icon">${icon(ico,25)}</span><div><h3>${title}</h3><p>${description}</p><div>${links.map(([url,label])=>`<a href="${url}">${label} ${icon('arrow',12)}</a>`).join('')}</div></div></article>`).join('')}</div><footer><p>在线 AI 是否可用取决于服务配置；本地工具不会虚构在线调用记录。</p><a href="#home">返回工作台 ${icon('arrow',15)}</a></footer></section></div><aside class="member-side"><section class="card member-card"><header><h2>账户服务</h2></header><p class="member-caption">登录后查看账户项目、主动上传的原件、后台任务与实际 AI 服务用量。本地草稿不会因为登录而自动上传。</p><div class="member-help"><a href="#projects?scope=account">${icon('folder',19)}<span>管理账户内容</span>${icon('arrow',16)}</a><a href="#account?view=usage">${icon('chart',19)}<span>查看实际用量</span>${icon('arrow',16)}</a><a href="#membership?scope=account">${icon('diamond',19)}<span>查看已有权益</span>${icon('arrow',16)}</a></div></section><section class="card member-card"><header><h2>使用与支持</h2></header><div class="member-help"><button id="member-policy">${icon('shield',19)}<span>当前服务说明</span>${icon('arrow',16)}</button><a href="#settings/data">${icon('file',19)}<span>本地数据与备份</span>${icon('arrow',16)}</a><a href="#help">${icon('help',19)}<span>帮助与反馈</span>${icon('arrow',16)}</a></div><p class="member-caption">会员与积分购买请进入购买中心，账户交易与本地资料分别管理。</p></section></aside></div><div class="member-backup">${icon('shield',26)}<div><b>研究资料，建议定期备份</b><p>更换设备或清理浏览器前，请分别保管本地备份和账户原件。</p></div><button class="btn secondary" data-workspace-backup>导出本地工作空间备份</button></div></div>`;
 $('#member-policy').onclick=()=>modal('当前服务说明',`<div class="member-policy"><h3>本地记录与账户记录</h3><p>本页只统计当前浏览器中已经保存的项目、草稿、文献和报告。账户项目、上传原件、任务与用量需在账户内容中查看，不会自动合并或上传本地资料。</p><h3>AI 服务用量与功能状态</h3><p>AI 服务使用情况由服务端记录；未返回的 Token 显示未知。保存草稿不属于 AI 服务调用。在线 AI、学术检索和各工具能力以对应页面实际状态为准，不以会员预览替代功能交付。</p><h3>当前购买范围</h3><p>科研积分提供 200 / 500 / 1000 三档，对应 20 / 50 / 100 元。订单价格与渠道状态以付款页面为准，余额仅在服务端核验支付后更新。会员及套餐规则以正式上架商品为准。</p><a class="btn secondary" href="#help?scope=account">提交账户反馈</a></div>`);
}
